r=pathlib.Path(__file__).resolve().parents[2];o=r/'test-results/t29';assert not(o/'consumer-path.txt').exists();d=pathlib.Path(tempfile.mkdtemp(prefix='templux-t29-consumer-',dir=r.parent));shutil.copytree(o/'releases/0.1.2-t29.1/project',d,dirs_exist_ok=True);(o/'consumer-path.txt').write_text(str(d));p=d/'apps/api/src/server.ts';p.write_text(p.read_text().replace('Project-owned business extension','Delta-owned business extension'));(d/'config/project-owned.json').write_text('{"owner":"Delta","purpose":"synthetic independent delivery"}\n');subprocess.run(['python3',str(r/'tests/scenarios/t29-consumer-images.py')],check=True);env={k:v for k,v in os.environ.items()if not k.startswith(('TEMPLUX_','COMPOSE_','FEISHU_'))and k!='DATABASE_URL'};env.update(TEMPLUX_PROJECT_NAME='t29-consumer',TEMPLUX_HOST_UID='0',TEMPLUX_HOST_GID='0');cmd=[str(d/'templux'),'init','--name','Delta Lab','--brand','Delta Lab','--theme','dark-brown','--confirm','--overwrite','--json'];p=subprocess.run(cmd,cwd=d,env=env,capture_output=True,text=True,timeout=120);(o/'consumer-init-images.stdout').write_text(p.stdout);(o/'consumer-init-images.stderr').write_text(p.stderr);assert p.returncode==0 and json.loads(p.stdout)['ok'];print('Owned image-backed consumer initialized')
